const r = await Promise.allSettled([
  tools.exec_command({cmd:"rg -n 'U2FSignRequest|GetU2FSignRequest|AuthenticateChallenge|u2f.*[Cc]hallenge|U2F.*[Cc]hallenge' --glob '*.go' tool lib | head -240",workdir:"/app",max_output_tokens:12000}),
  tools.exec_command({cmd:"rg --files -g 'AGENTS.md' -g '!vendor' -g '!node_modules' .",workdir:"/app",max_output_tokens:2000}),
  tools.exec_command({cmd:"git status --short",workdir:"/app",max_output_tokens:2000}),
]); for (const x of r) text(x.status === "fulfilled" ? x.value.output : String(x.reason));

const r = await Promise.allSettled([
 tools.exec_command({cmd:"find . -name AGENTS.md -print",workdir:"/app",max_output_tokens:2000}),
 tools.exec_command({cmd:"grep -RInE 'U2FSignRequest|GetU2FSignRequest|AuthenticateChallenge|u2f.*[Cc]hallenge|U2F.*[Cc]hallenge' --include='*.go' tool lib | head -240",workdir:"/app",max_output_tokens:12000}),
 tools.exec_command({cmd:"ls -la .codex-role-output",workdir:"/app",max_output_tokens:2000})
]); for (const x of r) text(x.status === "fulfilled" ? x.value.output : String(x.reason));

