				`"challenges":[{"version":"U2F_V2","challenge":"first","keyHandle":"first-key","appId":"https://example.com"},` +
				`{"version":"U2F_V2","challenge":"second","keyHandle":"second-key","appId":"https://example.com"}]}`,
			challenges: []string{"first", "second"},
		},
		{
			name:       "challenge list without legacy field",
			response:   `{"challenges":[{"version":"U2F_V2","challenge":"only","keyHandle":"only-key","appId":"https://example.com"}]}`,
			challenges: []string{"only"},
		},
		{
			name:      "missing challenge",
			response:  `{}`,
			wantError: true,
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			challenges, err := parseU2FSignChallenges([]byte(test.response))
			if test.wantError {
				require.Error(t, err)
				return
			}
			require.NoError(t, err)
			require.Len(t, challenges, len(test.challenges))
			for i, challenge := range challenges {
				require.Equal(t, test.challenges[i], challenge.Challenge)
			}
		})
	}
}

